const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';

const eventsApi = {
  getAllEvents: async () => {
    const response = await fetch(`${API_BASE_URL}/events`);
    if (!response.ok) throw new Error('Failed to fetch events');
    return response.json();
  },

  getMyEvents: async () => {
    const response = await fetch(`${API_BASE_URL}/events/my`);
    if (!response.ok) throw new Error('Failed to fetch my events');
    return response.json();
  },

  getEventById: async (id) => {
    const response = await fetch(`${API_BASE_URL}/events/${id}`);
    if (!response.ok) throw new Error('Failed to fetch event');
    return response.json();
  },

  createEvent: async (eventData) => {
    const response = await fetch(`${API_BASE_URL}/events`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(eventData),
    });
    if (!response.ok) throw new Error('Failed to create event');
    return response.json();
  },

  registerEvent: async (eventId) => {
    const response = await fetch(`${API_BASE_URL}/events/${eventId}/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
    });
    if (!response.ok) throw new Error('Failed to register for event');
    return response.json();
  },

  cancelRegistration: async (eventId) => {
    const response = await fetch(`${API_BASE_URL}/events/${eventId}/cancel`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
    });
    if (!response.ok) throw new Error('Failed to cancel registration');
    return response.json();
  },
};

export default eventsApi;
